//! In-memory lockdown peer for the pinned idevice client. Never compiled into the APK worker.
//! Public test key only; ephemeral host keys generated by idevice are never logged or saved.
use idevice::{Idevice, lockdown::LockdownClient};
use tokio::io::{AsyncReadExt, AsyncWriteExt, DuplexStream};
use std::time::Duration;

const PUBLIC_KEY: &str = "-----BEGIN RSA PUBLIC KEY-----\n\
MIIBCgKCAQEAqpE/irPmWh1JOW+hykwZb3UV4OPd9nuS4ccXdwvgBIYA0FY9upcX\n\
jJO5Az0My11+jzioKEFCl1Wbb/I9wRgBeAiI+M2tcKaoyjZ+uhGFL8XjZsEnjEgm\n\
P0ij6gDzA3r9AEALbK0XE+IZtYNXrhV3y7iel9YIBOR6faEE8ZCqzEHKas/+vm0B\n\
me5MUX0JYyUAbWer069CMAYH5crJould3sCkWPav7n2URK271X5JWVp2ARUFmFv9\n\
DKHy/uge3vwEFkN2kz4jzP4twPbrzhQkazU1Ng5AcqFCTWdRVKDizHLddq3Yt3JR\n\
MfoWndW0tJzomTDPPYLzskcDspC6GdPeXQIDAQAB\n-----END RSA PUBLIC KEY-----\n";

async fn request(peer: &mut DuplexStream) -> plist::Dictionary {
    let size = peer.read_u32().await.unwrap() as usize;
    assert!((1..=128 * 1024).contains(&size));
    let mut bytes = vec![0; size]; peer.read_exact(&mut bytes).await.unwrap();
    plist::from_bytes(&bytes).unwrap()
}
async fn reply(peer: &mut DuplexStream, value: plist::Value) {
    let mut bytes = Vec::new(); value.to_writer_xml(&mut bytes).unwrap();
    peer.write_u32(bytes.len() as u32).await.unwrap();
    for part in bytes.chunks(7) { peer.write_all(part).await.unwrap(); }
}
fn field(key: &str, value: impl Into<plist::Value>) -> plist::Value {
    let mut dictionary = plist::Dictionary::new(); dictionary.insert(key.into(), value.into());
    dictionary.into()
}
async fn serve(mut peer: DuplexStream, outcome: &'static str) {
    for (key, value) in [("DevicePublicKey", plist::Value::Data(PUBLIC_KEY.as_bytes().to_vec())),
        ("WiFiAddress", "00:00:00:00:00:00".into())] {
        let req = request(&mut peer).await;
        assert_eq!(req.get("Request").and_then(|v| v.as_string()), Some("GetValue"));
        assert_eq!(req.get("Key").and_then(|v| v.as_string()), Some(key));
        reply(&mut peer, field("Value", value)).await;
    }
    let first = request(&mut peer).await;
    assert_eq!(first.get("Request").and_then(|v| v.as_string()), Some("Pair"));
    if outcome == "detach" { return; }
    reply(&mut peer, field("Error", "PairingDialogResponsePending")).await;
    let second = request(&mut peer).await;
    assert!(first == second, "Pending Trust retry must preserve the exact pairing request");
    if outcome == "accepted" { reply(&mut peer, field("Request", "Pair")).await; }
    else { reply(&mut peer, field("Error", outcome)).await; }
    // The client drops the completed/failed connection; no unpair/reset/extra Pair.
    let mut byte = [0];
    assert_eq!(peer.read(&mut byte).await.unwrap(), 0);
}

#[tokio::test]
async fn pinned_pair_client_handles_pending_trust_accept_denial_lock_and_detach() {
    for (outcome, code) in [("accepted", None), ("UserDeniedPairing", Some("TRUST_DENIED")),
        ("PasswordProtected", Some("DEVICE_LOCKED")), ("detach", Some("PAIRING_TRANSPORT"))] {
        // Real RSA generation can exceed 20s alongside ARM64 APK builds.
        // Test watchdog only; production Trust deadlines are unchanged.
        tokio::time::timeout(Duration::from_secs(60), async {
            let (stream, peer) = tokio::io::duplex(256 * 1024);
            let server = tokio::spawn(serve(peer, outcome));
            let mut client = LockdownClient::new(Idevice::new(Box::new(stream), "virtual-test"));
            let result = client.pair("synthetic-host", "synthetic-buid", Some("test")).await;
            match code {
                None => assert!(result.is_ok(), "Synthetic Trust acceptance must produce a pairing record"),
                Some(expected) => match result {
                    Err(error) => assert_eq!(crate::lockdown_pairing::device_failure(error, "PAIRING_RESPONSE").code, expected),
                    Ok(_) => panic!("Synthetic rejection must fail"),
                },
            }
            drop(client);
            server.await.unwrap();
        }).await.expect("Virtual lockdown peer hung");
    }
}

#[tokio::test]
async fn canceled_silent_lockdown_peer_closes_without_cleanup_commands() {
    let (stream, mut peer) = tokio::io::duplex(4096);
    let mut client = LockdownClient::new(Idevice::new(Box::new(stream), "virtual-test"));
    let server = tokio::spawn(async move {
        let req = request(&mut peer).await;
        assert_eq!(req.get("Key").and_then(|v| v.as_string()), Some("DeviceName"));
        let mut byte = [0]; assert_eq!(peer.read(&mut byte).await.unwrap(), 0);
    });
    assert!(tokio::time::timeout(Duration::from_millis(50), client.get_value(Some("DeviceName"), None)).await.is_err());
    drop(client);
    tokio::time::timeout(Duration::from_secs(2), server).await.unwrap().unwrap();
}

#[tokio::test]
async fn wifi_preserves_enabled_setting_and_never_writes_unknown_state() {
    for previous in [plist::Value::Boolean(true), plist::Value::Boolean(false), "unknown".into()] {
        let (stream, mut peer) = tokio::io::duplex(4096);
        let prior = previous.clone();
        let server = tokio::spawn(async move {
            let req = request(&mut peer).await;
            assert_eq!(req.get("Key").and_then(|v| v.as_string()), Some("EnableWifiDebugging"));
            reply(&mut peer, field("Value", prior.clone())).await;
            if prior.as_boolean() == Some(false) {
                let req = request(&mut peer).await;
                assert_eq!(req.get("Request").and_then(|v| v.as_string()), Some("SetValue"));
                assert_eq!(req.get("Value").and_then(|v| v.as_boolean()), Some(true));
                reply(&mut peer, field("Request", "SetValue")).await;
            }
            let mut byte = [0]; assert_eq!(peer.read(&mut byte).await.unwrap(), 0);
        });
        let mut client = LockdownClient::new(Idevice::new(Box::new(stream), "virtual-test"));
        let result = crate::pairing::enable_wifi(&mut client).await;
        match previous.as_boolean() {
            Some(true) => assert!(matches!(result, Ok("UNCHANGED"))),
            Some(false) => assert!(matches!(result, Ok("CONFIRMED"))),
            None => assert!(matches!(result, Err(crate::Failure { code: "WIFI_DEBUGGING", .. }))),
        }
        drop(client); tokio::time::timeout(Duration::from_secs(2), server).await.unwrap().unwrap();
    }
}
